app.MapGet("/api/orders/recent", async (AppDbContext db) =>
{
    var cutoff = DateTime.UtcNow.AddDays(-30);
    var orders = await db.Orders
        .AsNoTracking()
        .Where(o => o.Date > cutoff)
        .OrderByDescending(o => o.Date)
        .Take(50)
        .ToListAsync();
    return Results.Ok(orders);
});

